// 1. Lista de IDs dos profissionais ativos fornecida por você
const IDS_PERMITIDOS = [
  "4471", "7038", "10183", "7081", "9369", 
  "9942", "9480", "9418", "6498", "9729", "4469"
];

const input = items[0].json;
let dentists = [];

// Trata a entrada (se é array direto ou objeto com chave de array)
if (Array.isArray(input)) { 
  dentists = input; 
} else { 
  for (let key in input) { 
    if (Array.isArray(input[key])) { dentists = input[key]; break; } 
  } 
}

const requests = [];

// Função para pegar data no fuso de SP
function getBrDate(days) {
  const d = new Date();
  const br = new Date(d.toLocaleString("en-US", {timeZone: "America/Sao_Paulo"}));
  br.setDate(br.getDate() + days);
  return br.toISOString().split('T')[0];
}

const today = getBrDate(0);
const tomorrow = getBrDate(1);

dentists.forEach(d => {
  // Tenta capturar o ID de várias formas comuns em APIs
  const rawId = d.id || d.ID || d.codigo || d.id_agenda || d.id_profissional;
  const idStr = rawId ? rawId.toString() : null;
  const nome = d.nome || d.Nome || d.nome_profissional || "Dentista";

  // 2. FILTRO: Só processa se o ID estiver na nossa lista de permitidos
  if (idStr && IDS_PERMITIDOS.includes(idStr)) {
    // Gera entrada para hoje
    requests.push({ 
      json: { 
        dentistId: idStr, 
        dentistName: nome, 
        dateToCheck: today 
      } 
    });
    // Gera entrada para amanhã
    requests.push({ 
      json: { 
        dentistId: idStr, 
        dentistName: nome, 
        dateToCheck: tomorrow 
      } 
    });
  }
});

return requests;

const results = [];
// Pega a hora atual no fuso de SP
const now = new Date(new Date().toLocaleString("en-US", {timeZone: "America/Sao_Paulo"}));

// --- CORREÇÃO DO ERRO DE ITEM PAIRING ---
// Trocamos .item.json por .last().json para evitar o erro de "Vários itens correspondentes"
const context = $('🔄 Loop (1 por vez)1').last().json; 
const apiResponse = items[0].json;

// PALAVRAS PARA IGNORAR (Blacklist)
const IGNORED_TERMS = [
    "FERIADO", "ALMOÇO", "ALMOCO", "BLOQUEIO", "REUNIÃO", "REUNIAO", 
    "SEM EXPEDIENTE", "FECHADO", "NÃO ATEN", "NAO ATEN", "VAZIO"
];

// INTERVALO DE FUNCIONAMENTO (09:00 - 19:45)
const START_MINUTES = 9 * 60; 
const END_MINUTES = 19 * 60 + 45;

if (!apiResponse || !apiResponse.horario) {
  return [{ json: { enviar: false, reason: "Sem agenda/horários" } }];
}

// --- LOGICA PARA PEGAR APENAS O DIA ATUAL DA REQUISIÇÃO ---
let slots = [];
if (Array.isArray(apiResponse.horario)) {
    // Se a API retornar vários dias, pegamos apenas o primeiro [0]
    // pois o Loop já está filtrando o dia correto na chamada da API
    if (apiResponse.horario.length > 0 && Array.isArray(apiResponse.horario[0])) {
        slots = apiResponse.horario[0];
    } else {
        slots = apiResponse.horario;
    }
}

for (const slot of slots) {
  // Ignora se não tiver ID de paciente ou se for 0
  if (!slot.id_paciente || slot.id_paciente === 0) continue;

  const rawH = slot.horario || "";
  if (!rawH.includes(':') || rawH.length < 5) continue;

  const hora = rawH.substring(0, 5).trim();
  let pacienteNomeRaw = rawH.substring(6).trim();

  // 1. Filtro de Expediente
  const [h, m] = hora.split(':').map(Number);
  const currentSlotMinutes = h * 60 + m;
  if (currentSlotMinutes < START_MINUTES || currentSlotMinutes > END_MINUTES) continue;

  // 2. Filtro de Blacklist de nomes
  if (!pacienteNomeRaw || pacienteNomeRaw.length < 2) continue;
  const nomeUpper = pacienteNomeRaw.toUpperCase();
  if (IGNORED_TERMS.some(term => nomeUpper.includes(term))) continue;

  // 3. Cálculo da data correta usando a data que veio do Loop
  const apptDate = new Date(`${context.dateToCheck} ${hora}:00`);
  const diff = (apptDate - now) / (1000 * 60 * 60);

  let tipo = null;
  let quando_texto = "hoje";

  if (diff > 23.1 && diff <= 24.9) { 
     tipo = '24h';
     quando_texto = "amanhã";
  } else if (diff > 11.1 && diff <= 12.9) {
     tipo = '12h';
     quando_texto = "amanhã";
  } else if (diff > 1.5 && diff <= 2.5) {
     tipo = '2h';
     quando_texto = "hoje";
  }

  // Ignora consultas que já passaram
  if (diff < 0) continue; 

  const currentHour = now.getHours();
  const isMadrugada = currentHour >= 22 || currentHour < 7;

  if (tipo && !isMadrugada) {
    results.push({
      json: { 
        id_log: `${slot.id_paciente}_${context.dateToCheck}_${tipo}`, 
        paciente: { nome: pacienteNomeRaw },
        id_paciente: slot.id_paciente,
        dentista: context.dentistName, 
        hora, 
        tipo,
        quando_texto, 
        enviar: true,
        dateToCheck: context.dateToCheck 
      }
    });
  }
}

// Se não houver nada para enviar, retorna um aviso informativo
if (results.length === 0) {
    return [{ json: { enviar: false, reason: "Nenhum alerta válido encontrado" } }];
}

return results;
